from sim.g1.control import WholeBody, STAND_QPOS, ComFeedback
import numpy as np
wb=WholeBody()
def reach(hand, tgt, com=(0.0,0.0)):
    q=STAND_QPOS.copy()
    t={'left_foot':[0.035,0.119,0],'right_foot':[0.035,-0.119,0],'com':list(com),hand:tgt}
    for i in range(300): q=wb.solve(q,t)
    p=wb.points(q)
    return np.linalg.norm(p[hand]-np.array(tgt)), p['com'][:2], p['pelvis'][2]
for hand in ['right_hand','left_hand']:
  for x in [0.3,0.4,0.5]:
    for y in [-0.25,-0.1,0.0,0.1,0.25]:
      for z in [0.9,1.1]:
        e,c,pz=reach(hand,[x,y,z])
        print(hand[:1],x,y,z,'err %.3f'%e,'com',np.round(c,3),'pz %.2f'%pz)
" 2>&1 | head -80

